#define R3D(a,A) mix(A*dot(p,A), p, cos(a)) + sin(a)*cross(p,A)

void mainImage( out vec4 o, in vec2 FC )
{
float i,j,d=.4,e,t=iTime;
vec3 p,q,r=iResolution;
o=vec4(0.);

for(i=0.;i++<64.&&d>1e-4;){
    p=vec3((FC.xy-.5*r.xy)/r.y,e)*2.;
    q=vec3(-1,2,0)/64.;
    p*=R3D(t*.3,q);

    for(j=0.;j++<8.;)
        p=abs(abs(p*log(abs(p/i)))-.02)-.2,
        //q=vec3(-1,2,0)/64.,
        d=max(max(p.x,p.z), p.y)/d,
        d-=dot(p,p)/2e4;

    e-=d;
}o+=vec4(exp(p),1)/i;
}
